let ui;
const demo={skills:[],references:[],scope:'TASK',researchSaved:false};
const control=(text,action)=>`<button class="btn" data-backend="${action}">${text}</button>`;
export function renderResearch(h){ui=h;return `<div class="page research-page"><div class="page-heading"><div><div class="eyebrow">RESEARCH / FROM EVIDENCE TO IDEAS</div><h1>把问题，研究明白。</h1><p>从资料与对标出发，让每个结论都有依据。</p></div>${control('＋ 新建研究','new-research')}</div><div class="backend-context"><a class="btn primary" href="#teardown">视频拆解 · 完整链路 →</a><a class="btn" href="#capabilities">对标、趋势与其他研究能力 →</a></div><section class="research-hero"><div><span class="eyebrow"><i class="red-dot"></i> CONTINUE YOUR EXPLORATION</span><h2>下一步创作，<br>从一个更好的问题开始。</h2><p>研究与项目相连，资料、依据和结论一起留下。</p></div><img src="assets/research.svg" alt="红色灵感圆点与水平轨道的研究视觉"></section><div class="research-layout"><aside class="research-list"><div class="panel-label">研究会话 · 示例</div>${['品牌表达：怎样建立可信的叙事？','对标研究：慢生活内容的表达方式','内容拆解：空间叙事的节奏'].map((x,i)=>`<button class="research-session ${i===0?'selected':''}" data-backend="session" data-index="${i}"><strong>${x}</strong><small>${i===0?'关联：向新而行 · 品牌企划':'独立研究会话'} · 已完成</small></button>`).join('')}<div class="research-evidence"><span class="badge green">2 份依据</span><p>品牌背景与目标<br>视觉方向参考</p><small>查看依据 → 核对结论 → 继续创作</small></div></aside><section class="research-result"><div class="panel-top"><strong id="research-title">品牌表达：怎样建立可信的叙事？</strong><span class="badge green">已完成 · 演示</span></div><div class="research-result-body"><div class="research-step">读取依据　 →　 比较分析　 →　 综合结论</div><h2>让品牌的主张，回到具体的体验。</h2><p>以“看见可能、持续探索、形成作品”为叙事线索，将抽象愿景连接到用户能够理解的工作过程。</p><div class="research-insight"><span>01 / 关键发现</span><h3>用实际工作解释品牌价值</h3><p>从问题出发，带入资料与研究，再形成可修改的成果。清晰的过程比空泛口号更容易理解。</p><span class="source-pill">依据 01 · 品牌背景与目标</span></div><div class="research-insight"><span>02 / 下一步建议</span><h3>先完成一版短叙事，再比较不同开头</h3><p>将结论带回项目，以持续对话打磨文本。这是固定示例，不是实际执行的研究结果。</p><span class="source-pill">依据 02 · 视觉方向参考</span></div><div class="backend-actions">${control('保存研究结果','save-research')}${control('带入项目继续创作 →','handoff')}</div><p class="backend-note">结果保存与项目衔接为本地交互演示；未请求正式研究接口。</p></div></section></div>${h.footer()}</div>`}
export function mountBackend(h,page){ui=h;
 if(page==='studio'){
 document.querySelector('.page-heading').insertAdjacentHTML('afterend',`<div class="backend-context"><span><i class="red-dot"></i> 项目持续协作</span><span>资料 2 · 研究 1 · 文本成果 1</span>${control('引用资料 / 研究','references')}${control('技能 · 可选多选','skills')}${control('版本历史','history')}</div>`);
 document.querySelector('.project-progress').insertAdjacentHTML('beforebegin','<div class="tree-heading">研究 <span>01</span></div><a class="tree-row" href="#research">品牌表达 · 研究结论 ↗</a>');
 document.querySelector('.composer-tools').insertAdjacentHTML('beforebegin','<div id="backend-reference-tags" class="backend-tags"></div>');
 document.querySelector('#model').innerHTML='<option>Kimi · 演示</option><option>DeepSeek · 演示</option><option>自定义模型 · 演示</option>';
 }
 if(page==='content')document.querySelector('.content-banner').insertAdjacentHTML('afterend',`<div class="backend-context"><span>资料：读取、提取与引用</span><span>成果：文本编辑与版本保存</span>${control('查看资料处理状态','processing')}${control('知识与事实确认','facts')}<a class="btn" href="#research">进入研究 →</a></div>`);
 if(page==='analytics'){
 document.querySelector('.analytics-tools').insertAdjacentHTML('beforeend',control('录入 / 导入','import-metrics'));
 document.querySelector('.analytics-aside-bottom').insertAdjacentHTML('beforebegin',`<div class="analytics-nav-label">运营工作</div>${control('运营任务','tasks')}`);

 }
 updateTags();
}
document.addEventListener('teardown-handoff',e=>{demo.references=[e.detail.reference];demo.scope='PROJECT'});
function updateTags(){const count=document.querySelector('#skill-count');if(count){count.textContent=demo.skills.length;document.querySelector('#skill-label').textContent=demo.skills.length?demo.skills.join(' · '):'添加专业技能'}const root=document.querySelector('#backend-reference-tags');if(root)root.innerHTML=demo.references.map(x=>`<span class="source-pill">${ui.esc(x)} · ${{TURN:'本次对话',TASK:'当前任务',PROJECT:'整个项目'}[demo.scope]}</span>`).join('')+demo.skills.map(x=>`<span class="badge">${ui.esc(x)}</span>`).join('');}
const close='<button class="btn" data-action="close">关闭</button>';
document.addEventListener('click',e=>{const t=e.target.closest('[data-backend]');if(!t||!ui)return;
 switch(t.dataset.backend){
 case 'references':ui.modal('把依据带入当前工作',`<p class="dialog-copy">选择资料、研究或成果，并明确引用范围。此处只保存本地选择。</p><div class="backend-choice">${['品牌背景与目标 · 资料','品牌表达 · 研究结论','品牌叙事初稿 · 文本成果'].map(x=>`<label><input type="checkbox" name="reference" value="${x}" ${demo.references.includes(x)?'checked':''}>${x}</label>`).join('')}</div><label class="field">引用范围<select id="reference-scope">${[['TURN','本次对话'],['TASK','当前任务'],['PROJECT','整个项目']].map(([k,v])=>`<option value="${k}" ${demo.scope===k?'selected':''}>${v}</option>`).join('')}</select></label>`,control('确认引用','apply-references'));break;
 case 'apply-references':demo.references=[...document.querySelectorAll('[name=reference]:checked')].map(x=>x.value);demo.scope=document.querySelector('#reference-scope').value;document.querySelector('#dialog').close();updateTags();break;
 case 'skills':ui.modal('按需添加专业技能',`<p class="dialog-copy">可不选，也可组合多个技能。通用对话始终可用。</p><div class="backend-choice">${['品牌叙事','内容结构','表达校对'].map(x=>`<label><input type="checkbox" name="skill" value="${x}" ${demo.skills.includes(x)?'checked':''}>${x}<span class="badge">演示版本 1</span></label>`).join('')}</div>`,control('使用所选技能','apply-skills'));break;
 case 'apply-skills':demo.skills=[...document.querySelectorAll('[name=skill]:checked')].map(x=>x.value);document.querySelector('#dialog').close();updateTags();ui.toast(`已选择 ${demo.skills.length} 个演示技能`);break;
 case 'history':ui.modal('文本成果 · 版本历史','<div class="backend-choice"><label><strong>v2 · 当前浏览器编辑</strong><span class="badge green">当前</span></label><label><strong>v1 · 品牌叙事初稿</strong><span>AI 示例</span></label></div><p class="dialog-copy">正式接入使用服务端版本检查。此处展示历史结构，不执行服务端恢复。</p>',close);break;
 case 'processing':ui.modal('资料读取与处理','<div class="backend-choice"><label>品牌背景与目标 · TXT<span class="badge green">已读取</span></label><label>视觉方向参考 · IMG<span class="badge green">可预览</span></label><label>生活方式访谈 · 音频<span class="badge">转录中 · 示例</span></label></div><p class="dialog-copy">处理状态对应资料入库与转录任务；进度为固定演示。</p>',close);break;
 case 'facts':ui.modal('知识与事实确认','<p class="dialog-copy">知识保留来源，事实经确认后再进入共享项目。</p><div class="research-insight"><h3>鑫世界以项目承载持续工作</h3><p>来源：品牌背景与目标</p><span class="badge green">已确认 · 示例</span></div><div class="research-insight"><h3>行业趋势判断</h3><p>尚需核对原始证据</p><span class="badge orange">待确认 · 示例</span></div>',close);break;
 case 'new-research':ui.modal('从一个问题开始研究','<label class="field">研究问题<input id="research-question" placeholder="你希望研究明白什么？"></label><label class="field">研究方式<select><option>资料分析</option><option>对标研究</option><option>内容拆解</option></select></label><p class="dialog-copy">创建后显示示例结果，不调用 AI 或采集服务。</p>',control('开始演示研究','start-research'));break;
 case 'start-research':{const question=document.querySelector('#research-question').value.trim();if(!question)return ui.toast('请先填写研究问题');document.querySelector('#research-title').textContent=question;document.querySelector('#dialog').close();ui.toast('已打开演示研究结果');break;}
 case 'session':document.querySelectorAll('.research-session').forEach(x=>x.classList.toggle('selected',x===t));document.querySelector('#research-title').textContent=t.querySelector('strong').textContent;ui.toast('切换会话标题；正文为共用展示样例');break;
 case 'save-research':demo.researchSaved=true;t.textContent='已保存到本地会话';ui.toast('本次浏览会话已标记保存');break;
 case 'handoff':demo.references=['品牌表达 · 研究结论'];location.hash='studio';ui.toast('已带入研究引用，继续项目协作');break;
 case 'tasks':ui.modal('运营任务 · 示例','<div class="backend-choice"><label>品牌视频剪辑<span class="badge">进行中</span></label><label>核对昨日数据<span class="badge orange">待开始</span></label><label>回复评论<span class="badge green">已完成</span></label></div><p class="dialog-copy">任务对应负责人、截止时间和状态。实际可编辑权限由服务端返回。</p>',close);break;
 case 'import-metrics':ui.modal('录入与导入账号日度数据','<p class="dialog-copy">正式流程：上传 → 校验新增与更新 → 确认保存。当前为固定示例，不读取文件或写入业务数据。</p><label class="field">平台<select><option>抖音</option><option>小红书</option></select></label><div class="research-insight"><strong>日度数据示例.csv</strong><p>字段：账号、日期、播放、曝光、互动、净增粉丝、数据截至时间</p></div>',control('预览示例校验','preview-import'));break;
 case 'preview-import':ui.modal('导入预览 · 校验结果','<div class="backend-choice"><label>新增记录<span>2 条</span></label><label>更新记录<span>1 条</span></label><label>无效记录<span>0 条</span></label></div><p class="dialog-copy">今日数据属于阶段快照；缺失曝光不补零。这是模拟校验结果。</p>',control('确认本地演示','confirm-import'));break;
 case 'confirm-import':document.querySelector('#dialog').close();ui.toast('导入演示完成，未写入正式数据');break;
 }
});
